  companyId: number;
  name: string;
  rewardType: 'discount' | 'product';
  requiredPoints: number;
  discountValue: number | null;
  freeProductId: number | null;
  isActive: boolean;
  description?: string;
  created_At: string;
  updated_at?: string;
}

