    "content": "import React, { useState, useEffect } from 'react';
import {
  IonPage, IonContent, IonList, IonItem, IonLabel, IonNote, IonBadge,
  IonInput, IonButton, IonModal, IonHeader, IonToolbar, IonTitle, IonButtons,
  IonIcon, IonSpinner, IonToast, IonAlert, IonSelect, IonSelectOption,
  IonToggle, IonTextarea, IonFab, IonFabButton, IonInfiniteScroll,
  IonInfiniteScrollContent, useIonViewWillEnter
} from '@ionic/react';
import {
  addOutline, createOutline, trashOutline,
  InputInputEventDetail, SelectChangeEventDetail, ToggleChangeEventDetail,
  TextareaInputEventDetail, SearchbarInputEventDetail
} from 'ionicons/icons';

// Custom components
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';

// User context
import { useUser } from '../contexts/UserContext';

// API
import {
  PosRewardCatalogItem,
  getAllPosRewardCatalogItems,
  createPosRewardCatalogItem,
  updatePosRewardCatalogItem,
  deletePosRewardCatalogItem,
  Product // Re-exporting Product interface from API file for convenience
} from '../api/posRewardCatalogItemApi'; // Import Product from the generated API file

// Assume productsApi.ts exists for fetching products for dropdown
// This is an assumption based on common patterns and the API contracts section
import { getAllProducts } from '../api/productsApi';

// CSS
import './PosRewardCatalogItemPage.css';

// Constants and Helpers
const toHermosillo = (utc: string | undefined): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString();
};

const REWARD_TYPES: { value: 'discount' | 'product' | ''; label: string }[] = [
  { value: 'discount', label: 'Descuento Monetario' },
  { value: 'product', label: 'Producto Gratis' },
];

interface RewardCatalogItemFormState {
  catalogItemId?: number; // Optional for create
  name: string;
  rewardType: 'discount' | 'product' | '';
  requiredPoints: number | ''; // Allow empty string for initial input state
  discountValue: number | null;
  freeProductId: number | null;
  isActive: boolean;
  description: string;
}

const PosRewardCatalogItemPage: React.FC = () => {
  const { companyId } = useUser();

  // State for data and UI interactions
  const [posRewardCatalogItems, setPosRewardCatalogItems] = useState<PosRewardCatalogItem[]>([]);
  const [products, setProducts] = useState<Product[]>([]); // State for products dropdown
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [formState, setFormState] = useState<RewardCatalogItemFormState>({
    name: '',
    rewardType: '',
    requiredPoints: '',
    discountValue: null,
    freeProductId: null,
    isActive: true,
    description: '',
  });
  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<PosRewardCatalogItem | null>(null);

  // Pagination and search
  const [searchText, setSearchText] = useState('');
  const [page, setPage] = useState(0);
  const [infiniteScrollDisabled, setInfiniteScrollDisabled] = useState(false);
  const itemsPerPage = 20; // Standard pagination size

  // Popover state for Header
  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  // Form field error states
  const [nameError, setNameError] = useState('');
  const [rewardTypeError, setRewardTypeError] = useState('');
  const [requiredPointsError, setRequiredPointsError] = useState('');
  const [discountValueError, setDiscountValueError] = useState('');
  const [freeProductIdError, setFreeProductIdError] = useState('');

  // Validation function
  const validateForm = () => {
    let valid = true;
    setNameError('');
    setRewardTypeError('');
    setRequiredPointsError('');
    setDiscountValueError('');
    setFreeProductIdError('');

    if (!formState.name.trim()) {
      setNameError('El nombre es requerido.');
      valid = false;
    }
    if (!formState.rewardType) {
      setRewardTypeError('El tipo de recompensa es requerido.');
      valid = false;
    }
    if (formState.requiredPoints === '' || Number(formState.requiredPoints) <= 0) {
      setRequiredPointsError('Los puntos requeridos deben ser un número positivo.');
      valid = false;
    }

    if (formState.rewardType === 'discount') {
      if (formState.discountValue === null || Number(formState.discountValue) <= 0) {
        setDiscountValueError('El valor del descuento debe ser un número positivo.');
        valid = false;
      }
    }

    if (formState.rewardType === 'product') {
      if (formState.freeProductId === null || Number(formState.freeProductId) <= 0) {
        setFreeProductIdError('Debe seleccionar un producto gratis.');
        valid = false;
      }
    }

    return valid;
  };

  // Fetch products for the select input
  const fetchProductsList = async () => {
    if (!companyId) return;
    try {
      const fetchedProducts = await getAllProducts(companyId);
      setProducts(fetchedProducts);
    } catch (err) {
      setError((err as Error).message ?? 'Error cargando productos.');
    }
  };

  // Fetch list of POS Reward Catalog Items
  const fetchPosRewardCatalogItems = async (
    reset: boolean = false,
    search: string = searchText,
    currentPage: number = page
  ) => {
    if (!companyId) return;

    setLoading(true);
    setError('');

    try {
      const data = await getAllPosRewardCatalogItems(companyId);
      // Client-side filtering for simplicity, can be moved to backend if dataset is very large
      const filteredData = search
        ? data.filter(item =>
            item.name.toLowerCase().includes(search.toLowerCase()) ||
            item.description?.toLowerCase().includes(search.toLowerCase()) ||
            item.rewardType.toLowerCase().includes(search.toLowerCase())
          )
        : data;

      if (reset) {
        setPosRewardCatalogItems(filteredData.slice(0, itemsPerPage));
        setPage(0);
        setInfiniteScrollDisabled(filteredData.length <= itemsPerPage);
      } else {
        const newItems = filteredData.slice(
          currentPage * itemsPerPage,
          (currentPage + 1) * itemsPerPage
        );
        setPosRewardCatalogItems(prev => [...prev, ...newItems]);
        setInfiniteScrollDisabled(
          posRewardCatalogItems.length + newItems.length >= filteredData.length
        );
      }
    } catch (err) {
      setError((err as Error).message ?? 'Error cargando elementos del catálogo de recompensas.');
    } finally {
      setLoading(false);
    }
  };

  // Initial load on mount
  useEffect(() => {
    fetchProductsList();
    fetchPosRewardCatalogItems(true);
  }, [companyId]);

  // Refetch data when entering the view (Ionic lifecycle) for fresh data
  useIonViewWillEnter(() => {
    fetchProductsList();
    fetchPosRewardCatalogItems(true);
  });

  // Handle search input change
  const handleSearchChange = (e: CustomEvent<SearchbarInputEventDetail>) => {
    const searchVal = e.detail.value ?? '';
    setSearchText(searchVal);
    // Debounce or trigger immediately
    fetchPosRewardCatalogItems(true, searchVal); // Reset and search immediately
  };

  const loadMoreItems = async (ev: CustomEvent<void>) => {
    if (infiniteScrollDisabled) {
      (ev.target as HTMLIonInfiniteScrollElement).complete();
      return;
    }

    const nextPage = page + 1;
    await fetchPosRewardCatalogItems(false, searchText, nextPage);
    setPage(nextPage);
    (ev.target as HTMLIonInfiniteScrollElement).complete();
  };

  const handleOpenCreateModal = () => {
    setIsEditing(false);
    setFormState({
      name: '',
      rewardType: '',
      requiredPoints: '',
      discountValue: null,
      freeProductId: null,
      isActive: true,
      description: '',
    });
    // Clear all errors when opening modal
    setNameError('');
    setRewardTypeError('');
    setRequiredPointsError('');
    setDiscountValueError('');
    setFreeProductIdError('');
    setShowModal(true);
  };

  const handleOpenEditModal = (item: PosRewardCatalogItem) => {
    setIsEditing(true);
    setFormState({
      catalogItemId: item.catalogItemId,
      name: item.name,
      rewardType: item.rewardType,
      requiredPoints: item.requiredPoints,
      discountValue: item.discountValue,
      freeProductId: item.freeProductId,
      isActive: item.isActive,
      description: item.description ?? '',
    });
    // Clear all errors when opening modal
    setNameError('');
    setRewardTypeError('');
    setRequiredPointsError('');
    setDiscountValueError('');
    setFreeProductIdError('');
    setShowModal(true);
  };

  const handleSave = async () => {
    if (!validateForm()) {
      return;
    }

    setSaving(true);
    setError('');

    const payload = {
      companyId: companyId,
      name: formState.name,
      rewardType: formState.rewardType as 'discount' | 'product',
      requiredPoints: Number(formState.requiredPoints), // Ensure number
      discountValue: formState.rewardType === 'discount' ? Number(formState.discountValue) : null,
      freeProductId: formState.rewardType === 'product' ? Number(formState.freeProductId) : null,
      isActive: formState.isActive,
      description: formState.description,
    };

    try {
      if (isEditing && formState.catalogItemId) {
        await updatePosRewardCatalogItem(formState.catalogItemId, payload);
        setError('¡Elemento de catálogo de recompensas actualizado exitosamente!');
      } else {
        await createPosRewardCatalogItem(payload);
        setError('¡Elemento de catálogo de recompensas creado exitosamente!');
      }
      setShowModal(false);
      await fetchPosRewardCatalogItems(true); // Refetch all to update list
    } catch (err) {
      setError((err as Error).message ?? `Error al ${isEditing ? 'actualizar' : 'crear'} el elemento de catálogo.`);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (itemToDelete && companyId) {
      setSaving(true);
      setError('');
      try {
        await deletePosRewardCatalogItem(itemToDelete.catalogItemId, companyId);
        setError('¡Elemento de catálogo de recompensas eliminado exitosamente!');
        await fetchPosRewardCatalogItems(true);
      } catch (err) {
        setError((err as Error).message ?? 'Error al eliminar el elemento de catálogo.');
      } finally {
        setSaving(false);
        setShowDeleteAlert(false);
        setItemToDelete(null);
      }
    }
  };

  const confirmDelete = (item: PosRewardCatalogItem) => {
    setItemToDelete(item);
    setShowDeleteAlert(true);
  };

  return (
    <IonPage className="pos-reward-catalog-item-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Catálogo de Recompensas POS"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonSearchbar
          placeholder="Buscar recompensas..."
          value={searchText}
          onIonInput={handleSearchChange}
          debounce={300}
        ></IonSearchbar>

        {loading && posRewardCatalogItems.length === 0 ? (
          <div className="ion-text-center ion-padding-top">
            <IonSpinner name="crescent" />
            <p>Cargando recompensas...</p>
          </div>
        ) : (
          <IonList className="pos-reward-catalog-item-list ion-margin-top">
            {posRewardCatalogItems.map((item) => (
              <IonItem key={item.catalogItemId} className="pos-reward-catalog-item-card">
                <IonLabel>
                  <h2>{item.name}</h2>
                  <p>
                    <strong>Puntos Requeridos:</strong>{' '}
                    <IonNote color="primary">
                      {item.requiredPoints.toFixed(2)}
                    </IonNote>
                  </p>
                  <p>
                    <strong>Tipo:</strong>{' '}
                    <IonBadge color={item.rewardType === 'discount' ? 'success' : 'tertiary'}>
                      {REWARD_TYPES.find(type => type.value === item.rewardType)?.label || item.rewardType}
                    </IonBadge>
                  </p>
                  {item.rewardType === 'discount' && item.discountValue !== null && (
                    <p>
                      <strong>Valor Descuento:</strong>{' '}
                      <IonNote color="success">
                        ${item.discountValue.toFixed(2)} MXN
                      </IonNote>
                    </p>
                  )}
                  {item.rewardType === 'product' && item.freeProductId !== null && (
                    <p>
                      <strong>Producto Gratis:</strong>{' '}
                      <IonNote color="secondary">
                        {products.find(p => p.productId === item.freeProductId)?.name || 'N/A'}
                      </IonNote>
                    </p>
                  )}
                  {item.description && <p>{item.description}</p>}
                  <p>
                    <IonNote>Creado: {toHermosillo(item.created_At)}</IonNote>
                    {item.updated_at && (
                      <IonNote className="ion-margin-start">Actualizado: {toHermosillo(item.updated_at)}</IonNote>
                    )}
                  </p>
                </IonLabel>
                <div className="pos-reward-catalog-item-actions">
                  <IonToggle
                    checked={item.isActive}
                    onIonChange={(e: CustomEvent<ToggleChangeEventDetail>) => {
                      // In-list toggle for isActive for quick updates, or make read-only and only edit in modal
                      // For this example, it's editable directly, requiring an update call.
                      // If read-only in list: disabled={true}
                      updatePosRewardCatalogItem(item.catalogItemId, { isActive: e.detail.checked })
                        .then(() => setError('Estado de actividad actualizado.'))
                        .catch(err => setError((err as Error).message ?? 'Error actualizando estado.'));
                      setPosRewardCatalogItems(prev => prev.map(rc => rc.catalogItemId === item.catalogItemId ? { ...rc, isActive: e.detail.checked } : rc));
                    }}
                    aria-label="Activo"
                    className="ion-margin-end"
                  />
                  <IonButton fill="clear" onClick={() => handleOpenEditModal(item)} aria-label="Editar">
                    <IonIcon icon={createOutline} />
                  </IonButton>
                  <IonButton fill="clear" color="danger" onClick={() => confirmDelete(item)} aria-label="Eliminar">
                    <IonIcon icon={trashOutline} />
                  </IonButton>
                </div>
              </IonItem>
            ))}
          </IonList>
        )}

        <IonInfiniteScroll
          onIonInfinite={loadMoreItems}
          threshold="100px"
          disabled={infiniteScrollDisabled || loading}
        >
          <IonInfiniteScrollContent
            loadingSpinner="crescent"
            loadingText="Cargando más recompensas..."
          ></IonInfiniteScrollContent>
        </IonInfiniteScroll>

        <IonFab vertical="bottom" horizontal="end" slot="fixed">
          <IonFabButton onClick={handleOpenCreateModal} aria-label="Agregar recompensa">
            <IonIcon icon={addOutline} />
          </IonFabButton>
        </IonFab>

        <IonModal isOpen={showModal} onDidDismiss={() => setShowModal(false)} className="pos-reward-catalog-item-modal">
          <IonHeader>
            <IonToolbar>
              <IonTitle>{isEditing ? 'Editar Recompensa' : 'Crear Recompensa'}</IonTitle>
              <IonButtons slot="end">
                <IonButton onClick={() => setShowModal(false)}>Cerrar</IonButton>
              </IonButtons>
            </IonToolbar>
          </IonHeader>
          <IonContent className="ion-padding">
            <div className="pos-reward-form-fields">
              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre de Recompensa *"
                  labelPlacement="floating"
                  value={formState.name}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => {
                    setFormState(p => ({ ...p, name: e.detail.value! }));
                    setNameError(''); // Clear error on input
                  }}
                  className={nameError ? 'ion-invalid ion-touched' : ''}
                  errorText={nameError}
                />
              </div>

              <div className="wizard-field-group">
                <IonSelect
                  fill="outline"
                  label="Tipo de Recompensa *"
                  labelPlacement="floating"
                  value={formState.rewardType}
                  onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => {
                    setFormState(p => ({ ...p, rewardType: e.detail.value! }));
                    setRewardTypeError('');
                  }}
                  className={rewardTypeError ? 'ion-invalid ion-touched' : ''}
                  errorText={rewardTypeError}
                >
                  <IonSelectOption value="" disabled>Seleccione un tipo</IonSelectOption>
                  {REWARD_TYPES.map(type => (
                    <IonSelectOption key={type.value} value={type.value}>
                      {type.label}
                    </IonSelectOption>
                  ))}
                </IonSelect>
              </div>

              <div className="wizard-field-group">
                <IonInput
                  fill="outline"
                  label="Puntos Requeridos *"
                  labelPlacement="floating"
                  type="number"
                  value={formState.requiredPoints}
                  onIonInput={(e: CustomEvent<InputInputEventDetail>) => {
                    setFormState(p => ({ ...p, requiredPoints: e.detail.value ? Number(e.detail.value) : '' }));
                    setRequiredPointsError('');
                  }}
                  className={requiredPointsError ? 'ion-invalid ion-touched' : ''}
                  errorText={requiredPointsError}
                />
              </div>

              {formState.rewardType === 'discount' && (
                <div className="wizard-field-group">
                  <IonInput
                    fill="outline"
                    label="Valor de Descuento (MXN) *"
                    labelPlacement="floating"
                    type="number"
                    value={formState.discountValue}
                    onIonInput={(e: CustomEvent<InputInputEventDetail>) => {
                      setFormState(p => ({ ...p, discountValue: e.detail.value ? Number(e.detail.value) : null }));
                      setDiscountValueError('');
                    }}
                    className={discountValueError ? 'ion-invalid ion-touched' : ''}
                    errorText={discountValueError}
                  />
                </div>
              )}

              {formState.rewardType === 'product' && (
                <div className="wizard-field-group">
                  <IonSelect
                    fill="outline"
                    label="Producto Gratis *"
                    labelPlacement="floating"
                    value={formState.freeProductId}
                    onIonChange={(e: CustomEvent<SelectChangeEventDetail>) => {
                      setFormState(p => ({ ...p, freeProductId: e.detail.value ? Number(e.detail.value) : null }));
                      setFreeProductIdError('');
                    }}
                    className={freeProductIdError ? 'ion-invalid ion-touched' : ''}
                    errorText={freeProductIdError}
                  >
                    <IonSelectOption value={null} disabled>Seleccione un producto</IonSelectOption>
                    {products.map(product => (
                      <IonSelectOption key={product.productId} value={product.productId}>
                        {product.name}
                      </IonSelectOption>
                    ))}
                  </IonSelect>
                </div>
              )}

              <div className="wizard-field-group ion-item ion-no-padding ion-align-items-center ion-justify-content-between">
                <IonLabel>Activo</IonLabel>
                <IonToggle
                  checked={formState.isActive}
                  onIonChange={(e: CustomEvent<ToggleChangeEventDetail>) =>
                    setFormState(p => ({ ...p, isActive: e.detail.checked }))
                  }
                  aria-label="Activo"
                />
              </div>

              <div className="wizard-field-group">
                <IonTextarea
                  fill="outline"
                  label="Descripción"
                  labelPlacement="floating"
                  value={formState.description}
                  onIonInput={(e: CustomEvent<TextareaInputEventDetail>) =>
                    setFormState(p => ({ ...p, description: e.detail.value! }))
                  }
                  rows={3}
                />
              </div>
            </div>

            <IonButton expand="block" onClick={handleSave} disabled={saving} className="ion-margin-top">
              {saving ? <IonSpinner name="dots" /> : (isEditing ? 'Guardar Cambios' : 'Crear Recompensa')}
            </IonButton>
          </IonContent>
        </IonModal>

        <IonAlert
          isOpen={showDeleteAlert}
          onDidDismiss={() => setShowDeleteAlert(false)}
          header={'Confirmar Eliminación'}
          message={`¿Estás seguro de que quieres eliminar la recompensa "${itemToDelete?.name}"?`}
          buttons=[
            {
              text: 'Cancelar',
              role: 'cancel',
            },
            {
              text: 'Eliminar',
              handler: handleDelete,
            },
          ]
        />

        <IonToast
          isOpen={!!error}
          message={error}
          duration={3000}
          onDidDismiss={() => setError('')}
          color={error.toLowerCase().includes('éxito') ? 'success' : 'danger'}
        />
      </IonContent>
    </IonPage>
  );
};

export default PosRewardCatalogItemPage;
